import csv
import io


def parse_csv(raw_csv: str):
    expected_width = 6
    reader = csv.reader(io.StringIO(raw_csv, newline=""), delimiter=",", quotechar='"')
    records = [row for row in reader if row and any(cell.strip() for cell in row)]

    if not records:
        return {"columns": [], "rows": []}

    header_index = next(
        (i for i, row in enumerate(records) if len(row) == expected_width),
        0,
    )

    def normalize(row):
        row = list(row)
        if len(row) < expected_width:
            row.extend([""] * (expected_width - len(row)))
        elif len(row) > expected_width:
            row = row[: expected_width - 1] + [",".join(row[expected_width - 1 :])]
        return row

    columns = normalize(records[header_index])
    rows = [normalize(row) for row in records[header_index + 1 :]]
    return {"columns": columns, "rows": rows}
